import sys

def main():
    data = sys.stdin.read().split()
    r, c = int(data[0]), int(data[1])
    rows = data[2:2 + r]
    g = [ch == '1' for row in rows for ch in row]
    N = r * c
    lab = [0] * N
    sizes = [0]
    for s in range(N):
        if g[s] and not lab[s]:
            k = len(sizes)
            lab[s] = k
            stack = [s]
            cnt = 0
            while stack:
                u = stack.pop()
                cnt += 1
                x, y = divmod(u, c)
                if x > 0 and g[u - c] and not lab[u - c]:
                    lab[u - c] = k
                    stack.append(u - c)
                if x < r - 1 and g[u + c] and not lab[u + c]:
                    lab[u + c] = k
                    stack.append(u + c)
                if y > 0 and g[u - 1] and not lab[u - 1]:
                    lab[u - 1] = k
                    stack.append(u - 1)
                if y < c - 1 and g[u + 1] and not lab[u + 1]:
                    lab[u + 1] = k
                    stack.append(u + 1)
            sizes.append(cnt)
    best = max(sizes)
    for u in range(N):
        if not g[u]:
            x, y = divmod(u, c)
            seen = set()
            if x > 0:
                seen.add(lab[u - c])
            if x < r - 1:
                seen.add(lab[u + c])
            if y > 0:
                seen.add(lab[u - 1])
            if y < c - 1:
                seen.add(lab[u + 1])
            seen.discard(0)
            tot = 1
            for k in seen:
                tot += sizes[k]
            if tot > best:
                best = tot
    print(best)

